const state  = $input.first().json;
const body   = $('Webhook').first().json.body || $('Webhook').first().json;
const guest  = $('Validate Token').first().json;

if (!state.party_can_pay) {
  throw new Error('Party is not ready for payment: items still unclaimed or subtotal mismatch');
}

const partySubtotal = Number(state.subtotal_required);
const tipPct        = Number(state.tip_percent);
const partyTipCents = Math.round(partySubtotal * tipPct / 100);
const guestSubtotal = Number(state.guest_subtotal_cents);
const guestTip      = partySubtotal > 0
  ? Math.round((guestSubtotal / partySubtotal) * partyTipCents)
  : 0;
const guestTotalDue = guestSubtotal + guestTip;

const amountPaidCents = Math.round(parseFloat(body.amount_paid_cents) || 0);

if (amountPaidCents < guestTotalDue) {
  throw new Error(`Amount paid (${amountPaidCents}) is less than total due (${guestTotalDue})`);
}

return [{
  json: {
    guest_id:          guest.guest_id,
    party_id:          guest.party_id,
    amount_paid_cents: amountPaidCents,
    guest_subtotal_cents: guestSubtotal,
    guest_tip_cents:   guestTip,
    guest_total_due:   guestTotalDue
  }
}];

const payment   = $input.first().json;
const validated = $('Validate Payment').first().json;
return [{
  json: {
    success:              true,
    payment_id:           payment.id,
    amount_paid_cents:    validated.amount_paid_cents,
    guest_subtotal_cents: validated.guest_subtotal_cents,
    guest_tip_cents:      validated.guest_tip_cents,
    guest_total_due:      validated.guest_total_due,
    created_at:           payment.created_at
  }
}];
